#include <stdio.h>

#define PI 3.14159

float calcularAreaCirculo(float radio) {
    return PI * radio * radio;
}

float calcularAreaRectangulo(float base, float altura) {
    return base * altura;
}

float calcularAreaTriangulo(float base, float altura) {
    return (base * altura) / 2.0;
}

int main() {
    int n, opcion, i;
    float resultado;

    printf("Cuantas figuras desea calcular? ");
    scanf("%d", &n);

    for (i = 0; i < n; i++) {
        printf("\nFigura %d:\n", i + 1);
        printf("1. Circulo\n2. Rectangulo\n3. Triangulo\nOpcion: ");
        scanf("%d", &opcion);

        if (opcion == 1) {
            float radio;
            printf("Radio: ");
            scanf("%f", &radio);
            resultado = calcularAreaCirculo(radio);
        } else if (opcion == 2) {
            float base, altura;
            printf("Base: ");
            scanf("%f", &base);
            printf("Altura: ");
            scanf("%f", &altura);
            resultado = calcularAreaRectangulo(base, altura);
        } else if (opcion == 3) {
            float base, altura;
            printf("Base: ");
            scanf("%f", &base);
            printf("Altura: ");
            scanf("%f", &altura);
            resultado = calcularAreaTriangulo(base, altura);
        } else {
            printf("Opcion invalida.\n");
            continue;
        }

        printf("Area: %.2f\n", resultado);
    }

    return 0;
}
```

